import{_ as l,a0 as o,w as p,s as d,ao as r,I as t,x as s,a1 as i,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"如何解密 Linux 版本信息 | LCTT x X-CMD","titleTemplate":false,"description":"如何解密 Linux 版本信息 | LCTT (202007) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何解密 Linux 版本信息 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何解密 Linux 版本信息 | LCTT (202007) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202007/20200708 How to decipher Linux release info","title":"如何解密 Linux 版本信息","tag":"202007","desc":""},"relativePath":"202007/20200708 How to decipher Linux release info.md","filePath":"[post].md"}'),c={name:"202007/20200708 How to decipher Linux release info.md"};function u(h,e,g,b,k,m){const a=o("Link");return p(),d("div",null,[e[15]||(e[15]=r(`<h1 id="如何解密-linux-版本信息" tabindex="-1">如何解密 Linux 版本信息 <a class="header-anchor" href="#如何解密-linux-版本信息" aria-label="Permalink to “如何解密 Linux 版本信息”">​</a></h1><blockquote><p>显示和解释有关 Linux 版本的信息比看起来要复杂一些。</p></blockquote><p><img src="https://images.idgesg.net/images/article/2020/07/linux_woman-with-laptop_keyboard_code_programmer_devops_by-christin-hume-via-unsplash_linux_-100850842-large.jpg" alt="christin hume / Linux / Modified by IDG Comm."></p><p>与引用一个简单的版本号不同，识别 Linux 版本有很多种方法。即使只是快速查看一下 <code>uname</code> 命令的输出，也可以告诉你一些信息。这些信息是什么，它告诉你什么？</p><p>在本文中，我们将认真研究 <code>uname</code> 命令的输出以及其他一些命令和文件提供的版本说明。</p><h3 id="使用-uname" tabindex="-1">使用 uname <a class="header-anchor" href="#使用-uname" aria-label="Permalink to “使用 uname”">​</a></h3><p>每当在 Linux 系统终端窗口中执行命令 <code>uname -a</code> 时，都会显示很多信息。那是因为这个小小的 <code>a</code> 告诉 <code>uname</code> 命令你想查看该命令能提供的<em>全部</em>输出。结果显示的内容将告诉你许多有关该系统的各种信息。实际上，显示的每一块信息都会告诉你一些关于系统的不同信息。</p><p>例如，<code>uname -a</code> 输出看起来像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>Linux dragonfly 5.4.0-37-generic #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>尽管这可能不太重要，但你可以使用一个按适当的顺序包含 <code>uname</code> 所有选项来显示相同的信息：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -snmrvpio</span></span>
<span class="line"><span>Linux dragonfly 5.4.0-37-generic #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><p>要将这一长串信息分解为单独的块，可以使用类似这样的 <code>for</code> 循环来遍历每个选项：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ for option in s n m r v p i o; do echo -n &quot;$option: &quot;; uname -$option; done</span></span>
<span class="line"><span>s: Linux</span></span>
<span class="line"><span>n: dragonfly</span></span>
<span class="line"><span>m: x86_64</span></span>
<span class="line"><span>r: 5.4.0-37-generic</span></span>
<span class="line"><span>v: #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020</span></span>
<span class="line"><span>p: x86_64</span></span>
<span class="line"><span>i: x86_64</span></span>
<span class="line"><span>o: GNU/Linux</span></span></code></pre></div><p>该循环显示了该选项提供了哪些信息。<code>uname</code> 手册页提供了每个选项的描述。以下是清单：</p><ul><li>Linux –- 内核名称（选项 <code>s</code>）</li><li>dragonfly –- 节点名（选项 <code>n</code>）</li><li>x86_64 –- 机器硬件名（选项 <code>m</code>）</li><li>5.4.0-37-generic –- 内核发布版本（选项 <code>r</code>）</li><li>#41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020 -- 内核版本（选项 <code>v</code>）</li><li>x86_64 –- 处理器（选项 <code>p</code>）</li><li>x86_64 –- 硬件平台（选项 <code>i</code>）</li><li>GNU/Linux –- 操作系统（选项 <code>o</code>）</li></ul><p>要更深入地研究显示的信息，请认真查看显示的内核发行数据。第四行中的 <code>5.4.0-37</code> 不仅仅是一串任意数字。每个数字都很重要。</p><ul><li><code>5</code> 表示内核版本</li><li><code>4</code> 表示主要版本</li><li><code>0</code> 表示次要版本</li><li><code>37</code> 表示最新补丁</li></ul><p>此外，在上面的循环中输出的第 5 行（内核版本）中的 <code>#41</code> 表示此发布版本已编译 41 次。</p><p>如果你只想显示所有信息中的一项，那么单个选项可能很有用。例如，命令 <code>uname -n</code> 可以仅告诉你系统名称，而 <code>uname -r</code> 仅可以告诉你内核发布版本。在盘点服务器或构建脚本时，这些和其他选项可能很有用。</p><p>在 Red Hat 系统时，<code>uname -a</code> 命令将提供相同种类的信息。这是一个例子：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ uname -a</span></span>
<span class="line"><span>Linux fruitfly 4.18.0-107.el8.x86_64 #1 SMP Fri Jun 14 13:46:34 UTC 2019 x86_64 x86_64 x86_64 GNU/Linux</span></span></code></pre></div><h3 id="发行版信息" tabindex="-1">发行版信息 <a class="header-anchor" href="#发行版信息" aria-label="Permalink to “发行版信息”">​</a></h3><p>如果你需要了解运行的发行版是什么，那么 <code>uname</code> 的输出不会对你有太大帮助。毕竟，内核版本与发行版不同。关于这个信息，你可以在 Ubuntu 和其他基于 Debian 的系统上使用 <code>lsb_release -r</code> 命令，而在 Red Hat 上可以显示 <code>/etc/redhat-release</code> 文件的内容。</p><p>对于 Debian 系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ lsb_release -r</span></span>
<span class="line"><span>Release: 20.04</span></span></code></pre></div><p>对于 Red Hat 及相关系统：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>Red Hat Enterprise Linux release 8.1 Beta (Ootpa)</span></span></code></pre></div><h3 id="使用-proc-version" tabindex="-1">使用 /proc/version <a class="header-anchor" href="#使用-proc-version" aria-label="Permalink to “使用 /proc/version”">​</a></h3><p><code>/proc/version</code> 文件还可以提供有关 Linux 版本的信息。该文件中提供的信息与 <code>uname -a</code> 输出有很多共同点。以下是例子。</p><p>在 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/version</span></span>
<span class="line"><span>Linux version 5.4.0-37-generic (buildd@lcy01-amd64-001) (gcc version 9.3.0 (Ubuntu 9.3.0-10ubuntu2)) #41-Ubuntu SMP Wed Jun 3 18:57:02 UTC 2020</span></span></code></pre></div><p>在 RedHat 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat /proc/version</span></span>
<span class="line"><span>Linux version 4.18.0-107.el8.x86_64 (mockbuild@x86-vm-09.build.eng.bos.redhat.com) (gcc version 8.3.1 20190507 (Red Hat 8.3.1-4) (GCC)) #1 SMP Fri Jun 14 13:46:34 UTC 2019</span></span></code></pre></div><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h3><p>Linux 系统提供了很多关于内核和发行版安装的信息。你只需要知道在哪里或如何寻找并理解它的含义。</p><hr>`,36)),t("p",null,[e[1]||(e[1]=s("via: ",-1)),i(a,{href:"https://www.networkworld.com/article/3565432/how-to-decipher-linux-release-info.html"},{default:n(()=>[...e[0]||(e[0]=[s("https://www.networkworld.com/article/3565432/how-to-decipher-linux-release-info.html",-1)])]),_:1})]),t("p",null,[e[6]||(e[6]=s("作者：",-1)),i(a,{href:"https://www.networkworld.com/author/Sandra-Henry_Stocker/"},{default:n(()=>[...e[2]||(e[2]=[s("Sandra Henry-Stocker",-1)])]),_:1}),e[7]||(e[7]=s(" 选题：",-1)),i(a,{href:"https://github.com/lujun9972"},{default:n(()=>[...e[3]||(e[3]=[s("lujun9972",-1)])]),_:1}),e[8]||(e[8]=s(" 译者：",-1)),i(a,{href:"https://github.com/geekpi"},{default:n(()=>[...e[4]||(e[4]=[s("geekpi",-1)])]),_:1}),e[9]||(e[9]=s(" 校对：",-1)),i(a,{href:"https://github.com/wxy"},{default:n(()=>[...e[5]||(e[5]=[s("wxy",-1)])]),_:1})]),t("p",null,[e[12]||(e[12]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...e[10]||(e[10]=[s("LCTT",-1)])]),_:1}),e[13]||(e[13]=s(" 原创编译，",-1)),i(a,{href:"https://linux.cn/"},{default:n(()=>[...e[11]||(e[11]=[s("Linux中国",-1)])]),_:1}),e[14]||(e[14]=s(" 荣誉推出",-1))])])}const L=l(c,[["render",u]]);export{C as __pageData,L as default};
